{
  "name": "Beer Distribution Game",
  "brief": {
    "situation": "You run one company in a four-company supply chain ({$inputs.roles|list}) for one product. Only you can see your own position.",
    "rules": "Every week you first ship what you can to the company below you (the factory ships nothing; it produces instead), then place an order with the company above you one week ahead. Orders reach the supplier the week after you place them. A shipment you make arrives at the company below two weeks later along that link; the factory's production arrives as its own stock two weeks later. You start with {$inputs.initial_stock} cases in stock and {$inputs.pipeline_order} cases already on the way on each link (an order placed before week 1 that arrives in week 1). Unfilled demand becomes backlog, shown to you as it arrives; you must ship it before sending any new stock. Each company pays {$inputs.holding_cost|money} per case in stock and {$inputs.backlog_cost|money} per case of backlog at the end of every week. The game lasts {$inputs.horizon} weeks and the team's goal is the lowest total cost.",
    "roles": {
      "retailer": "You are the retailer. Shipping to customers: in each week of your ship turn set the quantity you sell to customers, capped by your available cases. Your demand below you is the customer demand of that week; backlog it creates must be shipped before new stock.",
      "wholesaler": "You are the wholesaler. Your ship action sends cases to the retailer from your own stock, capped by the cases you have available.",
      "distributor": "You are the distributor. Your ship action sends cases to the wholesaler from your own stock, capped by the cases you have available.",
      "factory": "You are the factory. You take no customer orders; instead of shipping your production action starts cases of production, which arrives in your own stock two weeks later."
    }
  },
  "clock": {"rounds": "$inputs.horizon", "unit": "week"},
  "inputs": {
    "horizon": {"type": "int", "default": 20, "min": 1, "max": 200, "display": "number", "label": "Weeks", "description": "How many weeks the game lasts."},
    "roles": {"type": "list", "default": ["retailer", "wholesaler", "distributor", "factory"], "items": {"type": "text", "required": true}, "description": "The companies in the chain, from the customer end (index 0) to the factory (last)."},
    "demand_min": {"type": "int", "default": 0, "min": 0, "max": 100, "display": "number", "label": "Lowest weekly demand"},
    "demand_max": {"type": "int", "default": 8, "min": 0, "max": 100, "display": "number", "label": "Highest weekly demand"},
    "initial_stock": {"type": "int", "default": 12, "min": 0, "display": "number", "label": "Starting stock"},
    "pipeline_order": {"type": "int", "default": 4, "min": 0, "display": "number", "label": "Cases already on the way on each link"},
    "ship_lead_time": {"type": "int", "default": 2, "min": 0, "max": 10, "display": "number", "label": "Weeks for a shipment to arrive"},
    "production_lead_time": {"type": "int", "default": 2, "min": 0, "max": 10, "display": "number", "label": "Weeks for production to arrive"},
    "holding_cost": {"type": "number", "default": 0.5, "min": 0, "display": "number", "label": "Cost per case in stock per week", "multiple_of": 0.01},
    "backlog_cost": {"type": "number", "default": 1.0, "min": 0, "display": "number", "label": "Cost per case of backlog per week", "multiple_of": 0.01},
    "production_default": {"type": "int", "default": 4, "min": 0, "max": 100, "display": "number", "label": "Default weekly production", "description": "What the factory produces in a week if the agent makes no choice."}
  },
  "world": {
    "demand_now": 0,
    "orders_last": {},
    "pipeline_at_or_under_empty": {},
    "current_positions": {}
  },
  "types": {
    "role": {
      "agent": true,
      "props": {
        "index": {"type": "int", "default": 0},
        "stock": {"type": "int", "default": 0, "min": 0},
        "backlog": {"type": "int", "default": 0, "min": 0},
        "incoming": {"type": "int", "default": 0, "min": 0},
        "outbound_up": {"type": "int", "default": 0, "min": 0},
        "just_received": {"type": "int", "default": 0},
        "incoming_orders": {"type": "int", "default": 0},
        "pending_orders": {"type": "list", "default": []},
        "shipped": {"type": "int", "default": 0},
        "customer_orders": {"type": "int", "default": 0},
        "last_order": {"type": "int", "default": 0},
        "orders_placed": {"type": "list", "default": []},
        "orders_shipped": {"type": "list", "default": []},
        "shipped_list": {"type": "list", "default": []},
        "stock_cost": {"type": "number", "default": 0},
        "backlog_cost": {"type": "number", "default": 0},
        "total_cost": {"type": "number", "default": 0}
      }
    }
  },
  "population": [
    {
      "type": "role",
      "from": "$inputs.roles",
      "id": "$row",
      "name": "$row",
      "props": {
        "index": "$i - 1",
        "stock": "$inputs.initial_stock"
      },
      "brief": "You are the {$row}. Your company is {name}. Your upstream supplier is the company above you, your customer is the company below you."
    }
  ],
  "actions": {
    "ship": {
      "by": "role",
      "description": "Ship cases from your stock to your customer company (or sell to customers if you are the customer-facing company). Capped by what you have available; 0 is allowed. To your supplier this looks like an order request; the supplier ships it as soon as it can.",
      "params": {
        "quantity": {"type": "int", "min": 0, "max": "$actor.stock + $actor.backlog", "description": "Cases to ship to your customer this week."}
      },
      "when": ["$actor.index > 0"],
      "do": [
        "$shipped = $min($params.quantity, $actor.stock + $actor.backlog)",
        "$actor.shipped = $shipped",
        "$actor.orders_shipped += $shipped",
        "$actor.shipped_list += $shipped",
        "$unmet = $params.quantity - $shipped",
        {"if": "$actor.backlog > 0", "then": [
          "$actor.backlog = $max(0, $actor.backlog - $shipped)",
          "$actor.stock -= $max(0, $shipped - $actor.backlog)"
        ], "else": [
          "$actor.stock -= $shipped"
        ]},
        "$actor.backlog += $unmet",
        {"if": "$actor.index == 1", "then": ["$actor.customer_orders = $params.quantity"]},
        {"if": "$actor.index < $len($inputs.roles) - 1", "then": [
          "$down = $entity($get($inputs.roles, $actor.index - 1))",
          "$down.incoming = $world.map_lt[$down.id] + $shipped"
        ]}
      ],
      "outcome": "Shipped {$actor.shipped} cases; {$unmet} cases of demand went to backlog. Stock {$actor.stock}, backlog {$actor.backlog}."
    },
    "order": {
      "by": "role",
      "description": "Place your order with your supplier company one week ahead. It arrives in their inbox next week; they ship it two weeks after that.",
      "params": {
        "quantity": {"type": "int", "min": 0, "max": 100, "default": 4, "description": "Cases to order from your supplier."}
      },
      "when": ["$actor.index < $len($inputs.roles) - 1"],
      "do": [
        {"if": "$actor.pending_orders == []", "then": [
          "$actor.pending_orders = $inputs.pipeline_order"
        ]},
        "$actor.pending_orders += $params.quantity",
        "$actor.last_order = $params.quantity",
        "$actor.orders_placed += $params.quantity",
        "$up = $entity($get($inputs.roles, $actor.index + 1))",
        "$up.incoming_orders += $params.quantity"
      ],
      "outcome": "Ordered {$params.quantity} cases from your supplier (week {$round}); they arrive next week and are shipped two weeks later."
    },
    "produce": {
      "by": "role",
      "description": "Start cases of production at the factory. What you start this week arrives in your own stock two weeks later, in addition to any production already started.",
      "params": {
        "quantity": {"type": "int", "min": 0, "max": 100, "default": 4, "description": "Cases to start producing this week."}
      },
      "when": ["$round == 1"],
      "do": [
        "$actor.pipeline = $inputs.pipeline_order + $params.quantity",
        "$actor.orders_placed += $params.quantity,
        "$actor.production_started += $params.quantity"
      ],
      "outcome": "Started {$params.quantity} cases of production; {$actor.pipeline} cases are due in your stock in week {$round + $inputs.production_lead_time}."
    }
  },
  "stages": [
    {
      "name": "decide",
      "brief": "Week {$round} of {$inputs.horizon}. Ship first, then order from your supplier one week ahead (the factory starts production instead).",
      "max_actions": 10,
      "max_calls": 100,
      "on_idle": [
        "A=$actor.backlog",
        "$actor.backlog = $max(0, $actor.backlog - $actor.stock)",
        "$actor.stock -= $min($actor.stock, $A)",
        "$actor.shipped = $min($actor.stock, $A)"
      ]
    },
    {
      "name": "advance",
      "on_enter": [
        "$world.tmp_positions = {}",
        {"each": "role", "do": [
          "$world.tmp_positions[$it.id] = [$it.stock, $it.backlog, $it.incoming, $it.outbound_up]"
        ]},
        "$world.tmp_arrivals = {}",
        {"each": "role", "do": [
          "$world.tmp_arrivals[$it.id] = [$it.pipeline_new, $it.incoming_new]"
        ]}
      ]
    }
  ],
  "events": [
    {
      "name": "demand",
      "phase": "start",
      "do": [
        "$world.demand_now = $randint($inputs.demand_min, $inputs.demand_max)",
        "$world.demand_list += $world.demand_now",
        {"each": "role", "do": ["$it.incoming = 0"]},
        "$retailer = $entity($get($inputs.roles, 0))",
        "$retailer.incoming = $retailer.incoming + $world.demand_now"
      ],
      "say": "Customers want {$world.demand_now} cases this week."
    },
    {
      "name": "receive",
      "phase": "start",
      "do": [
        "$world.map_lt = {}",
        {"each": "role", "do": [
          "$world.map_lt[$it.id] = $it.incoming"
        ]}
      ]
    },
    {
      "name": "apply_arrivals",
      "phase": "start",
      "do": [
        {"each": "role", "do": [
          "__dummy__"
        ]}
      ]
    },
    {
      "name": "costs",
      "phase": "end",
      "do": [
        {"each": "role", "do": [
          "$it.stock_cost = $round($it.stock * $inputs.holding_cost * 100) / 100",
          "$it.backlog_cost = $round($it.backlog * $inputs.backlog_cost * 100) / 100",
          "$it.total_cost = $round(($it.total_cost + $it.stock_cost + $it.backlog_cost) * 100) / 100"
        ]}
      ],
      "say": "Weekly costs were charged on stock and backlog."
    }
  ],
  "views": {
    "week": {"show": "Week {$round} of {$inputs.horizon}. Your role: {$actor.type|title}."},
    "mine": {"show": "Your company: stock {stock}, backlog {backlog}, available {stock + backlog}. Cases arriving this week: {just_received}. Deliveries arriving from your supplier this week: {incoming}. Orders received from your customer last week: {incoming_orders}. Cases of your last shipment still on the way to your customer: {outbound_up}."},
    "cost": {"show": "Costs so far: {$actor.total_cost|money} (holding {$actor.stock_cost|money}, backlog {$actor.backlog_cost|money} last week)."},
    "history": {"show": "You shipped {shipped_list|list} cases in weeks 1..{$round}; you placed supplier orders {orders_placed|list}."}
  },
  "metrics": {
    "weekly_cost": {"expr": "$sum(role, $it.stock_cost + $it.backlog_cost)", "unit": "$"},
    "stock_cost": {"expr": "$sum(role, $it.stock_cost)", "unit": "$"},
    "backlog_cost": {"expr": "$sum(role, $it.backlog_cost)", "unit": "$"},
    "backlog": {"expr": "$sum(role, $it.backlog)", "unit": "cases"},
    "stock": {"expr": "$sum(role, $it.stock)", "unit": "cases"},
    "demand": {"expr": "$world.demand_now", "unit": "cases"}
  },
  "outputs": {
    "customer_demand": {"expr": "$world.demand_list", "type": "list", "description": "Cases customers demanded each week, in week order."},
    "factory_orders": {"expr": "$world.production_list", "type": "list", "description": "Cases the factory put into production each week, in week order."},
    "costs_by_role": {"expr": "$dict($sort(role, $it.index), $it.id, $it.total_cost)", "type": "map", "description": "Total cost of each company."},
    "total_team_cost": {"expr": "$sum(role, $it.total_cost)", "type": "number", "format": "money", "description": "Sum of all four companies' costs."},
    "bullwhip_ratio": {"expr": "$variance($world.production_list) / $variance($world.demand_list)", "type": "number", "format": 2, "description": "Variance of the factory's weekly production orders divided by the variance of weekly customer demand."}
  }
}

{
  "name": "Beer Distribution Game",
  "brief": {
    "situation": "You run one company in a supply chain of {$len($inputs.roles)} companies for a single product. The chain runs from the customer-facing company to the factory: {$inputs.roles|list}. You only ever see your own position: your stock, your backlog, the orders your customer sends you and the deliveries that reach you. You never see the other companies' positions.",
    "rules": "Each week: deliveries reach you, orders your customer sent last week reach you, customers buy, then you automatically ship what you can to your customer (demand you cannot fill becomes backlog and is shipped later, before new stock), and finally you place an order with your supplier (the factory instead starts production). Orders reach your supplier the following week, and the supplier ships them as soon as it can; shipments take {$inputs.ship_lead_time} weeks to arrive, and the factory's production takes {$inputs.production_lead_time} weeks to arrive in its own stock. You start with {$inputs.initial_stock} cases in stock and {$inputs.pipeline_order} cases already on the way on each shipping link. Every week's end you pay {$inputs.holding_cost|money} per case in stock and {$inputs.backlog_cost|money} per case of backlog. The game lasts {$inputs.horizon} weeks; the team's goal is the lowest total cost.",
    "roles": {
      "role": "You are one company in the chain. Your private brief tells you which one you are, who your supplier is and who your customer is."
    }
  },
  "clock": {"rounds": "$inputs.horizon", "unit": "week"},
  "inputs": {
    "horizon": {"type": "int", "default": 20, "min": 1, "max": 200, "display": "number", "label": "Weeks", "description": "How many weeks the game lasts."},
    "roles": {"type": "list", "default": ["retailer", "wholesaler", "distributor", "factory"], "items": {"type": "text", "required": true}, "description": "Companies in the chain, from the customer end (index 0) up to the factory (last)."},
    "demand_min": {"type": "int", "default": 0, "min": 0, "max": 100, "display": "number", "label": "Lowest weekly customer demand"},
    "demand_max": {"type": "int", "default": 8, "min": 0, "max": 100, "display": "number", "label": "Highest weekly customer demand"},
    "initial_stock": {"type": "int", "default": 12, "min": 0, "display": "number", "label": "Starting stock per company"},
    "pipeline_order": {"type": "int", "default": 4, "min": 0, "display": "number", "label": "Cases already on the way on each shipping link"},
    "ship_lead_time": {"type": "int", "default": 2, "min": 1, "max": 10, "display": "number", "label": "Weeks for a shipment to arrive"},
    "production_lead_time": {"type": "int", "default": 2, "min": 1, "max": 10, "display": "number", "label": "Weeks for production to arrive"},
    "holding_cost": {"type": "number", "default": 0.5, "min": 0, "display": "number", "label": "Cost per case in stock per week", "multiple_of": 0.01},
    "backlog_cost": {"type": "number", "default": 1.0, "min": 0, "display": "number", "label": "Cost per case of backlog per week", "multiple_of": 0.01},
    "production_default": {"type": "int", "default": 4, "min": 0, "max": 100, "display": "number", "label": "Factory's default weekly production", "description": "What the factory produces in a week if it ends its turn without choosing."}
  },
  "world": {
    "demand_now": 0,
    "demand_list": [],
    "production_list": []
  },
  "types": {
    "role": {
      "agent": true,
      "inspect": false,
      "props": {
        "index": {"type": "int", "default": 0},
        "stock": {"type": "int", "default": 0, "min": 0},
        "backlog": {"type": "int", "default": 0, "min": 0},
        "arrivals": {"type": "list", "default": []},
        "production": {"type": "list", "default": []},
        "orders_next_week": {"type": "int", "default": 0},
        "arrived": {"type": "int", "default": 0},
        "incoming_orders": {"type": "int", "default": 0},
        "shipped": {"type": "int", "default": 0},
        "shipped_list": {"type": "list", "default": []},
        "orders_placed": {"type": "list", "default": []},
        "last_order": {"type": "int", "default": 0},
        "produced_week": {"type": "int", "default": 0},
        "stock_cost": {"type": "number", "default": 0},
        "backlog_cost": {"type": "number", "default": 0},
        "total_cost": {"type": "number", "default": 0}
      }
    }
  },
  "population": [
    {
      "type": "role",
      "from": "$inputs.roles",
      "id": "$row",
      "name": "$row",
      "props": {
        "index": "$i - 1",
        "stock": "$inputs.initial_stock",
        "arrivals": "$set_at($map($range($inputs.ship_lead_time), 0), 0, $inputs.pipeline_order if $i - 1 < $len($inputs.roles) - 1 else 0)",
        "production": "$map($range($inputs.production_lead_time), 0)"
      },
      "brief": "You are the {$row}. Your supplier is the company directly above you in the chain; your customer is the company directly below you."
    }
  ],
  "actions": {
    "order": {
      "by": "role",
      "private": true,
      "description": "Place your weekly order with your supplier. It reaches them next week and they ship it as soon as they can, after the shipping lead time. Choose 0 to order nothing.",
      "params": {
        "quantity": {"type": "int", "min": 0, "max": 100, "default": 4, "description": "Cases to order from your supplier this week."}
      },
      "when": ["$actor.index < $len($inputs.roles) - 1"],
      "per_round": 1,
      "do": [
        "$up = $entity($get($inputs.roles, $actor.index + 1))",
        "$up.orders_next_week += $params.quantity",
        "$actor.last_order = $params.quantity",
        "$actor.orders_placed += $params.quantity"
      ],
      "outcome": "You ordered {$params.quantity} cases from your supplier in week {$round}."
    },
    "produce": {
      "by": "role",
      "private": true,
      "description": "Start cases of production at the factory. What you start this week arrives in your own stock after the production lead time. Choose 0 to produce nothing.",
      "params": {
        "quantity": {"type": "int", "min": 0, "max": 100, "default": 4, "description": "Cases to start producing this week."}
      },
      "when": ["$actor.index == $len($inputs.roles) - 1"],
      "per_round": 1,
      "do": [
        "$actor.production[$inputs.production_lead_time - 1] += $params.quantity",
        "$actor.produced_week += $params.quantity"
      ],
      "outcome": "You started {$params.quantity} cases of production in week {$round}."
    }
  },
  "stages": [
    {
      "name": "decide",
      "who": "role",
      "max_actions": 2,
      "max_calls": 12,
      "brief": "Week {$round} of {$inputs.horizon}. Deliveries, customer orders and shipping have been handled. Decide this week's order (the factory decides production).",
      "on_idle": [
        {"if": "$actor.index == $len($inputs.roles) - 1", "then": [
          "$actor.production[$inputs.production_lead_time - 1] += $inputs.production_default",
          "$actor.produced_week += $inputs.production_default"
        ]}
      ]
    }
  ],
  "events": [
    {
      "name": "arrivals",
      "phase": "start",
      "when": "$len($inputs.roles) > 0",
      "do": [
        {"each": "role", "do": [
          "$it.arrived = $it.arrivals[0]",
          "$it.stock += $it.arrived",
          "$it.arrivals = $slice($it.arrivals, 1)",
          "$it.arrivals += 0",
          {"if": "$it.index == $len($inputs.roles) - 1", "then": [
            "$it.stock += $it.production[0]",
            "$it.production = $slice($it.production, 1)",
            "$it.production += 0"
          ]}
        ]}
      ]
    },
    {
      "name": "receive_orders",
      "phase": "start",
      "when": "$len($inputs.roles) > 0",
      "do": [
        {"each": "role", "do": [
          "$it.incoming_orders = $it.orders_next_week",
          "$it.backlog += $it.incoming_orders",
          "$it.orders_next_week = 0
        ]}
      ]
    },
    {
      "name": "customer_demand",
      "phase": "start",
      "when": "$len($inputs.roles) > 0",
      "do": [
        "$world.demand_now = $randint($inputs.demand_min, $inputs.demand_max)",
        "$world.demand_list += $world.demand_now",
        "$retailer = $entity($get($inputs.roles, 0))",
        "$retailer.incoming_orders = $world.demand_now",
        "$retailer.backlog += $world.demand_now"
      ],
      "say": "Customers want {$world.demand_now} cases this week."
    },
    {
      "name": "auto_ship",
      "phase": "start",
      "when": "$len($inputs.roles) > 0",
      "do": [
        {"each": "role", "do": [
          "$it.shipped = $min($it.stock, $it.backlog)",
          "$it.stock -= $it.shipped",
          "$it.backlog -= $it.shipped",
          "$it.shipped_list += $it.shipped",
          {"if": "$it.index > 0", "then": [
            "$dn = $entity($get($inputs.roles, $it.index - 1))",
            "$dn.arrivals[$inputs.ship_lead_time - 1] += $it.shipped"
          ]}
        ]}
      ]
    },
    {
      "name": "costs",
      "phase": "end",
      "when": "$len($inputs.roles) > 0",
      "do": [
        {"each": "role", "do": [
          "$it.stock_cost = $round($it.stock * $inputs.holding_cost * 100) / 100",
          "$it.backlog_cost = $round($it.backlog * $inputs.backlog_cost * 100) / 100",
          "$it.total_cost = $round(($it.total_cost + $it.stock_cost + $it.backlog_cost) * 100) / 100"
        ]}
      ],
      "say": "Weekly holding and backlog costs were charged at every company."
    },
    {
      "name": "record_production",
      "phase": "end",
      "when": "$len($inputs.roles) > 0",
      "do": [
        {"each": "role", "where": "$it.index == $len($inputs.roles) - 1", "do": [
          "$world.production_list += $it.produced_week",
          "$it.produced_week = 0"
        ]}
      ]
    }
  ],
  "views": {
    "week": {"show": "Week {$round} of {$inputs.horizon}. You are {$actor.id}."},
    "mine": {"show": "Stock {$actor.stock}; backlog {$actor.backlog}; cases that arrived this week {$actor.arrived}; orders received from your customer this week {$actor.incoming_orders}; cases you shipped to your customer this week {$actor.shipped}."},
    "orders": {"show": "Your supplier orders so far: {$actor.orders_placed|list}. Your weekly shipments: {$actor.shipped_list|list}."},
    "cost": {"show": "Cost so far: {$actor.total_cost|money} (holding {$actor.stock_cost|money} and backlog {$actor.backlog_cost|money} last week)."},
    "board": {"for": "spectator", "of": "role", "sort": "$it.index", "title": "Supply chain (spectator)", "show": "{id}: stock {stock}, backlog {backlog}, cost {total_cost}"}
  },
  "metrics": {
    "weekly_cost": {"expr": "$sum(role, $it.stock_cost + $it.backlog_cost)", "unit": "$"},
    "holding_cost": {"expr": "$sum(role, $it.stock_cost)", "unit": "$"},
    "backlog_cost": {"expr": "$sum(role, $it.backlog_cost)", "unit": "$"},
    "stock": {"expr": "$sum(role, $it.stock)", "unit": "cases"},
    "backlog": {"expr": "$sum(role, $it.backlog)", "unit": "cases"},
    "customer_demand": {"expr": "$world.demand_now", "unit": "cases"}
  },
  "outputs": {
    "customer_demand": {"expr": "$world.demand_list", "type": "list", "description": "Cases customers demanded each week, in week order."},
    "factory_orders": {"expr": "$world.production_list", "type": "list", "description": "Cases the factory put into production each week, in week order."},
    "costs_by_role": {"expr": "$dict($sort(role, $it.index), $it.id, $it.total_cost)", "type": "map", "description": "Total cost of each company, keyed by role."},
    "total_team_cost": {"expr": "$sum(role, $it.total_cost)", "type": "number", "format": "money", "description": "Sum of all companies' costs."},
    "bullwhip_ratio": {"expr": "($variance($world.production_list) or 0) / ($variance($world.demand_list) or 1)", "type": "number", "format": "2", "description": "Variance of the factory's weekly production orders divided by the variance of weekly customer demand."}
  },
  "invariants": [
    {"expr": "$all(role, $it.stock >= 0)", "why": "Stock cannot go negative."},
    {"expr": "$all(role, $it.backlog >= 0)", "why": "Backlog cannot go negative."}
  ]
}
